-- Connected planning/IOU/savings regression. All fixture auth, state and postings roll back.
begin;
create function pg_temp.planning_assert(v boolean,label text)returns void language plpgsql as $$begin
 if v is distinct from true then raise exception 'Planning check failed: %',label;end if;
 perform set_config('lumo.planning.checks',(coalesce(nullif(current_setting('lumo.planning.checks',true),''),'0')::integer+1)::text,true);
end $$;
create function pg_temp.planning_call(command text,payload jsonb default '{}')returns jsonb language plpgsql as $$declare r jsonb;begin
 execute 'set local role authenticated';r:=public.lumo_rpc(command,payload);execute 'reset role';return r;
 exception when others then execute 'reset role';raise;end $$;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();p uuid:=gen_random_uuid();x uuid:=gen_random_uuid();sa uuid:=gen_random_uuid();sb uuid:=gen_random_uuid();sp uuid:=gen_random_uuid();sx uuid:=gen_random_uuid();
 suffix text:=substr(replace(gen_random_uuid()::text,'-',''),1,8);pin text:=lpad(floor(random()*1000000)::integer::text,6,'0');
 r jsonb;original jsonb;other jsonb;plan jsonb;plain_box uuid;protected_box uuid;invitation uuid;release_id uuid;iou_id uuid;food uuid;transport uuid;hack_id uuid;manual_record uuid;recovery_id uuid;first_receipt uuid;merchant_shop uuid;merchant_payment uuid;creation_code text;withdrawal_code text;
 before_balance bigint;before_count bigint;before_revision bigint;saved_categories jsonb;expected_balance bigint;
begin
 perform set_config('lumo.planning.checks','0',true);
 insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,created_at,updated_at)values
 (a,'authenticated','authenticated','planning-a-'||suffix||'@example.invalid',now(),'{"lumo_pilot":true}',now(),now()),
 (b,'authenticated','authenticated','planning-b-'||suffix||'@example.invalid',now(),'{"lumo_pilot":true}',now(),now()),
 (p,'authenticated','authenticated','planning-p-'||suffix||'@example.invalid',now(),'{"lumo_pilot":true}',now(),now()),
 (x,'authenticated','authenticated','planning-x-'||suffix||'@example.invalid',now(),'{"lumo_pilot":true}',now(),now());
 insert into auth.sessions(id,user_id,created_at,updated_at)values(sa,a,now(),now()),(sb,b,now(),now()),(sp,p,now(),now()),(sx,x,now(),now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);
 r:=pg_temp.planning_call('account.open',jsonb_build_object('handle','pa_'||suffix,'displayName','Planning A','pin',pin));perform pg_temp.planning_assert(r->>'ok'='true','A opens account');
 r:=pg_temp.planning_call('wallet.fund',jsonb_build_object('amount',10000,'confirmSandbox',true,'attemptId','planning-a-fund-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','A test funding');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id',sb)::text,true);
 r:=pg_temp.planning_call('account.open',jsonb_build_object('handle','pb_'||suffix,'displayName','Planning B','pin',pin));perform pg_temp.planning_assert(r->>'ok'='true','B opens account');
 r:=pg_temp.planning_call('wallet.fund',jsonb_build_object('amount',10000,'confirmSandbox',true,'attemptId','planning-b-fund-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','B test funding');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',p,'role','authenticated','session_id',sp)::text,true);
 r:=pg_temp.planning_call('account.open',jsonb_build_object('handle','pp_'||suffix,'displayName','Planning Partner','pin',pin));perform pg_temp.planning_assert(r->>'ok'='true','partner opens account');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',x,'role','authenticated','session_id',sx)::text,true);
 r:=pg_temp.planning_call('account.open',jsonb_build_object('handle','px_'||suffix,'displayName','Planning Outsider','pin',pin));perform pg_temp.planning_assert(r->>'ok'='true','outsider opens account');
 perform pg_temp.planning_assert(not has_function_privilege('authenticated','lumo_private.planning_command(text,jsonb)','EXECUTE'),'private command cannot bypass session guard');
 perform pg_temp.planning_assert(not has_table_privilege('authenticated','lumo_private.money_boxes','SELECT,UPDATE'),'no direct savings table access');
 perform pg_temp.planning_assert(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='lumo_private'and c.relkind='r'and not c.relrowsecurity),'all private tables RLS');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);
 r:=pg_temp.planning_call('plan.get');perform pg_temp.planning_assert((r#>>'{plan,revision}')::integer=0 and(r#>>'{plan,leftAfterPlan}')::bigint=10000,'initial plan does not invent funds');
 r:=pg_temp.planning_call('plan.save',jsonb_build_object('revision',0,'periodStart',current_date,'periodEnd',current_date+29,'allowanceDate',current_date-1,'expectedAllowance',50000,'keepBack',500,'categories',jsonb_build_array(jsonb_build_object('name','Food','amount',6000),jsonb_build_object('name','Transport','amount',1000)),'attemptId','planning-plan-save-'||suffix));
 plan:=r->'plan';food:=(plan#>>'{categories,0,id}')::uuid;transport:=(plan#>>'{categories,1,id}')::uuid;
 perform pg_temp.planning_assert(r->>'ok'='true'and(plan->>'plannedRemaining')::bigint=7500 and(plan->>'leftAfterPlan')::bigint=2500,'Essentials plus keepback separate from expected allowance');
 original:=r;r:=pg_temp.planning_call('plan.save',jsonb_build_object('revision',0,'periodStart',current_date,'periodEnd',current_date+29,'allowanceDate',current_date-1,'expectedAllowance',50000,'keepBack',500,'categories',jsonb_build_array(jsonb_build_object('name','Food','amount',6000),jsonb_build_object('name','Transport','amount',1000)),'attemptId','planning-plan-save-'||suffix));
 perform pg_temp.planning_assert(r->>'replayed'='true'and r->'plan'=original->'plan','plan retry exactly once');
 r:=pg_temp.planning_call('plan.save',jsonb_build_object('revision',0,'periodStart',current_date,'periodEnd',current_date+29,'categories',jsonb_build_array(jsonb_build_object('name','Food','amount',1)),'attemptId','planning-plan-stale-'||suffix));perform pg_temp.planning_assert(r->>'code'='PLAN_CHANGED','stale device cannot overwrite plan');
 saved_categories:=plan->'categories';before_revision:=(plan->>'revision')::bigint;
 r:=pg_temp.planning_call('plan.save',jsonb_build_object('revision',before_revision,'periodStart',current_date,'periodEnd',current_date+29,'categories',jsonb_build_array(jsonb_build_object('id',food,'name','Food changed','amount',5000),jsonb_build_object('id',gen_random_uuid(),'name','Foreign','amount',2000)),'attemptId','planning-plan-invalid-tail-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','invalid later category fails whole update');
 r:=pg_temp.planning_call('plan.get');perform pg_temp.planning_assert(r#>'{plan,categories}'=saved_categories and(r#>>'{plan,revision}')::bigint=before_revision,'failed plan leaves every category and revision unchanged');
 r:=pg_temp.planning_call('box.create',jsonb_build_object('name','Laptop','goal',20000,'attemptId','planning-box-create-'||suffix));plain_box:=(r#>>'{box,id}')::uuid;perform pg_temp.planning_assert(r->>'ok'='true'and(r#>>'{box,balance}')::bigint=0 and r#>>'{box,protected}'='false','new box starts zero without phantom funds');
 r:=pg_temp.planning_call('box.save',jsonb_build_object('boxId',plain_box,'amount',1500,'pin',pin,'attemptId','planning-box-save-'||suffix));original:=r;
 perform pg_temp.planning_assert(r->>'ok'='true'and(r#>>'{account,balance}')::bigint=8500 and(r#>>'{box,balance}')::bigint=1500 and r#>>'{receipt,type}'='box_save','box save genuinely debits Everyday');
 r:=pg_temp.planning_call('box.save',jsonb_build_object('boxId',plain_box,'amount',1500,'pin',pin,'attemptId','planning-box-save-'||suffix));perform pg_temp.planning_assert(r->>'replayed'='true'and r#>>'{receipt,id}'=original#>>'{receipt,id}'and(r#>>'{account,balance}')::bigint=8500,'box save retry no double debit');
 r:=pg_temp.planning_call('box.withdraw',jsonb_build_object('boxId',plain_box,'amount',500,'pin',pin,'attemptId','planning-box-withdraw-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true'and(r#>>'{account,balance}')::bigint=9000 and(r#>>'{box,balance}')::bigint=1000,'withdraw transfers real box funds back');
 r:=pg_temp.planning_call('box.partner.invite',jsonb_build_object('partnerHandle','pp_'||suffix,'attemptId','planning-partner-invite-'||suffix));invitation:=(r#>>'{invitation,id}')::uuid;perform pg_temp.planning_assert(invitation is not null,'partner invitation persisted');
 select count(*)into before_count from lumo_private.money_boxes where owner_user_id=a;
 r:=pg_temp.planning_call('box.create',jsonb_build_object('name','Protected','goal',5000,'partnerInvitationId',invitation,'partnerCode','000000','attemptId','planning-box-before-accept-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false'and(select count(*)from lumo_private.money_boxes where owner_user_id=a)=before_count,'cannot create protected box before partner consent');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',p,'role','authenticated','session_id',sp)::text,true);
 r:=pg_temp.planning_call('box.list');perform pg_temp.planning_assert(jsonb_array_length(r->'partnerInvitations')=1 and not(r->>'partnerCode'is not null),'partner sees invitation without owner funds or leaked code');
 r:=pg_temp.planning_call('box.partner.respond',jsonb_build_object('invitationId',invitation,'accept',true,'pin',pin,'attemptId','planning-partner-accept-'||suffix));creation_code:=r->>'partnerCode';perform pg_temp.planning_assert(r->>'ok'='true'and creation_code~'^[0-9]{6}$','accepted partner receives creation code');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);
 r:=pg_temp.planning_call('box.list');perform pg_temp.planning_assert(not(r::text like'%'||creation_code||'%'),'owner list cannot read partner code');
 r:=pg_temp.planning_call('box.create',jsonb_build_object('name','Protected','goal',5000,'partnerInvitationId',invitation,'partnerCode',creation_code,'attemptId','planning-protected-create-'||suffix));protected_box:=(r#>>'{box,id}')::uuid;perform pg_temp.planning_assert(r->>'ok'='true'and r#>>'{box,protected}'='true','code completes protected box creation');
 r:=pg_temp.planning_call('box.create',jsonb_build_object('name','Reuse','goal',5000,'partnerInvitationId',invitation,'partnerCode',creation_code,'attemptId','planning-protected-code-reuse-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','creation code cannot protect another box');
 r:=pg_temp.planning_call('box.update',jsonb_build_object('boxId',protected_box,'protected',false,'attemptId','planning-protection-bypass-'||suffix));perform pg_temp.planning_assert(r->>'code'='PARTNER_APPROVAL_REQUIRED','editing cannot remove partner protection');
 r:=pg_temp.planning_call('box.save',jsonb_build_object('boxId',protected_box,'amount',1000,'pin',pin,'attemptId','planning-protected-save-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','protected box funded');
 r:=pg_temp.planning_call('box.withdraw',jsonb_build_object('boxId',protected_box,'amount',200,'pin',pin,'attemptId','planning-protected-bypass-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','protected withdrawal cannot bypass approval');
 r:=pg_temp.planning_call('box.release.request',jsonb_build_object('boxId',protected_box,'amount',200,'attemptId','planning-release-request-'||suffix));release_id:=(r#>>'{release,id}')::uuid;perform pg_temp.planning_assert(release_id is not null,'withdrawal exact amount request created');
 r:=pg_temp.planning_call('box.release.decide',jsonb_build_object('releaseId',release_id,'approve',true,'pin',pin,'attemptId','planning-release-self-'||suffix));perform pg_temp.planning_assert(r->>'code'='FORBIDDEN','owner cannot self approve partner release');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',p,'role','authenticated','session_id',sp)::text,true);
 r:=pg_temp.planning_call('box.release.decide',jsonb_build_object('releaseId',release_id,'approve',true,'pin',pin,'attemptId','planning-release-approve-'||suffix));withdrawal_code:=r->>'partnerCode';perform pg_temp.planning_assert(r->>'ok'='true'and withdrawal_code~'^[0-9]{6}$','partner receives amount bound withdrawal code');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);
 r:=pg_temp.planning_call('box.withdraw',jsonb_build_object('boxId',protected_box,'amount',200,'releaseId',release_id,'pin',pin,'attemptId','planning-release-missing-code-'||suffix));perform pg_temp.planning_assert(r->>'code'='SECRET_REQUIRED'and r->>'definitive'='false','missing partner credential keeps original attempt retryable');
 r:=pg_temp.planning_call('box.withdraw',jsonb_build_object('boxId',protected_box,'amount',201,'releaseId',release_id,'partnerCode',withdrawal_code,'pin',pin,'attemptId','planning-release-forged-amount-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','partner approval cannot change amount');
 r:=pg_temp.planning_call('box.withdraw',jsonb_build_object('boxId',protected_box,'amount',200,'releaseId',release_id,'partnerCode',withdrawal_code,'pin',pin,'attemptId','planning-release-withdraw-'||suffix));original:=r;perform pg_temp.planning_assert(r->>'ok'='true'and(r#>>'{box,balance}')::bigint=800,'protected withdraw consumes approval with PIN');
 r:=pg_temp.planning_call('box.withdraw',jsonb_build_object('boxId',protected_box,'amount',200,'releaseId',release_id,'partnerCode',withdrawal_code,'pin',pin,'attemptId','planning-release-withdraw-'||suffix));perform pg_temp.planning_assert(r->>'replayed'='true'and r#>>'{receipt,id}'=original#>>'{receipt,id}','protected withdraw replay does not need new approval');
 r:=pg_temp.planning_call('box.withdraw',jsonb_build_object('boxId',protected_box,'amount',200,'releaseId',release_id,'partnerCode',withdrawal_code,'pin',pin,'attemptId','planning-release-code-reuse-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','approval cannot debit twice with fresh attempt');
 r:=pg_temp.planning_call('iou.create',jsonb_build_object('counterpartyHandle','pb_'||suffix,'direction','lend','amount',2000,'dueDate',current_date+1,'note','Books','attemptId','planning-iou-create-'||suffix));iou_id:=(r#>>'{iou,id}')::uuid;perform pg_temp.planning_assert(r->>'ok'='true'and r#>>'{iou,status}'='pending','IOU starts awaiting other persons consent');
 r:=pg_temp.planning_call('iou.respond',jsonb_build_object('iouId',iou_id,'accept',true,'attemptId','planning-iou-self-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','IOU creator cannot accept for other person');
 r:=pg_temp.planning_call('insight.get');before_balance:=(r#>>'{insights,available}')::bigint;perform pg_temp.planning_assert((r#>>'{insights,owedToYou}')::bigint=0,'unconfirmed IOU not counted as accepted debt');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id',sb)::text,true);
 r:=pg_temp.planning_call('iou.pay',jsonb_build_object('iouId',iou_id,'amount',500,'pin',pin,'attemptId','planning-iou-before-accept-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','unaccepted IOU cannot trigger payment');
 r:=pg_temp.planning_call('iou.respond',jsonb_build_object('iouId',iou_id,'accept',true,'attemptId','planning-iou-accept-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true'and r#>>'{iou,status}'='active','other person accepts IOU');
 r:=pg_temp.planning_call('iou.pay',jsonb_build_object('iouId',iou_id,'amount',500,'pin',pin,'attemptId','planning-iou-pay-'||suffix));original:=r;perform pg_temp.planning_assert(r->>'ok'='true'and(r#>>'{iou,remaining}')::bigint=1500 and r#>>'{receipt,type}'='iou_payment','partial IOU payment real debit credit');
 r:=pg_temp.planning_call('iou.pay',jsonb_build_object('iouId',iou_id,'amount',500,'pin',pin,'attemptId','planning-iou-pay-'||suffix));perform pg_temp.planning_assert(r->>'replayed'='true'and r#>>'{receipt,id}'=original#>>'{receipt,id}','IOU retry once only');
 r:=pg_temp.planning_call('iou.pay',jsonb_build_object('iouId',iou_id,'amount',1501,'pin',pin,'attemptId','planning-iou-overpay-'||suffix));perform pg_temp.planning_assert(r->>'code'='IOU_OVERPAYMENT','IOU overpayment rejected');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);
 r:=pg_temp.planning_call('insight.get');perform pg_temp.planning_assert((r#>>'{insights,available}')::bigint=before_balance+500 and(r#>>'{insights,owedToYou}')::bigint=1500,'only actually repaid IOU increases available balance');
 r:=pg_temp.planning_call('iou.remind',jsonb_build_object('iouId',iou_id,'attemptId','planning-iou-remind-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','creditor can remind accepted IOU');
 r:=pg_temp.planning_call('iou.remind',jsonb_build_object('iouId',iou_id,'attemptId','planning-iou-remind-again-'||suffix));perform pg_temp.planning_assert(r->>'code'='REMINDER_LIMIT','reminder throttled centrally');
 r:=pg_temp.planning_call('hack.save',jsonb_build_object('boxId',plain_box,'rule','percent','value',10,'enabled',true,'attemptId','planning-hack-save-'||suffix));hack_id:=(r#>>'{hack,id}')::uuid;perform pg_temp.planning_assert(hack_id is not null,'savings hack persisted');
 r:=pg_temp.planning_call('transfer',jsonb_build_object('recipientHandle','pb_'||suffix,'amount',400,'budgetCategoryId',food,'pin',pin,'attemptId','planning-budget-payment-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','payment with owned Essentials source succeeds');
 r:=pg_temp.planning_call('plan.get');perform pg_temp.planning_assert((select(value->>'spent')::bigint from jsonb_array_elements(r#>'{plan,categories}')where value->>'id'=food::text)=400,'posted payment consumes exact budget source');
 r:=pg_temp.planning_call('box.list');perform pg_temp.planning_assert((select(value->>'balance')::bigint from jsonb_array_elements(r->'boxes')where value->>'id'=plain_box::text)=1040,'percentage hack saves from actual post-payment funds');
 select balance into before_balance from lumo_private.accounts where owner_user_id=a and kind='consumer';select count(*)into before_count from lumo_private.journals;
 r:=pg_temp.planning_call('transfer',jsonb_build_object('recipientHandle','pb_'||suffix,'amount',100,'budgetCategoryId',gen_random_uuid(),'pin',pin,'attemptId','planning-budget-forged-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','forged budget source rejected');
 perform pg_temp.planning_assert((select balance from lumo_private.accounts where owner_user_id=a and kind='consumer')=before_balance and(select count(*)from lumo_private.journals)=before_count,'invalid source rolls back entire payment and hack');
 r:=pg_temp.planning_call('transfer',jsonb_build_object('recipientHandle','pb_'||suffix,'amount',6000,'budgetCategoryId',food,'pin',pin,'attemptId','planning-budget-over-'||suffix));perform pg_temp.planning_assert(r->>'ok'='false','budget cannot be spent beyond remaining allocation');
 perform pg_temp.planning_assert((select balance from lumo_private.accounts where owner_user_id=a and kind='consumer')=before_balance,'over budget leaves available unchanged');
 r:=pg_temp.planning_call('plan.get');plan:=r->'plan';before_revision:=(plan->>'revision')::bigint;saved_categories:=plan->'categories';
 r:=pg_temp.planning_call('plan.save',jsonb_build_object('revision',before_revision,'periodStart',current_date,'periodEnd',current_date+29,'categories',jsonb_build_array(jsonb_build_object('id',transport,'name','Transport changed','amount',1000)),'attemptId','planning-budget-drop-spent-'||suffix));perform pg_temp.planning_assert(r->>'code'='BUDGET_HAS_SPENDING','cannot remove category with actual spending');
 r:=pg_temp.planning_call('plan.get');perform pg_temp.planning_assert(r#>'{plan,categories}'=saved_categories,'omitted spent category rejection leaves other names unchanged');
 r:=pg_temp.planning_call('recovery.save',jsonb_build_object('checkInDate',current_date+3,'dailyLimit',500,'protectedCategoryIds',jsonb_build_array(food),'adjustments',jsonb_build_array(jsonb_build_object('categoryId',transport,'amount',500)),'attemptId','planning-recovery-save-'||suffix));recovery_id:=(r#>>'{recovery,id}')::uuid;perform pg_temp.planning_assert(r->>'ok'='true'and r#>>'{recovery,status}'='active','recovery and flexible budget reduction persisted');
 r:=pg_temp.planning_call('transfer',jsonb_build_object('recipientHandle','pb_'||suffix,'amount',100,'pin',pin,'attemptId','planning-recovery-payment-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','recovery does not fabricate or block valid actual payment');
 r:=pg_temp.planning_call('box.list');perform pg_temp.planning_assert((select(value->>'balance')::bigint from jsonb_array_elements(r->'boxes')where value->>'id'=plain_box::text)=1040,'active recovery pauses automatic hacks centrally');
 r:=pg_temp.planning_call('recovery.finish',jsonb_build_object('recoveryId',recovery_id,'attemptId','planning-recovery-finish-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true'and r#>>'{recovery,status}'='completed','owner can complete shared recovery');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id',sb)::text,true);
 r:=pg_temp.planning_call('merchant.create',jsonb_build_object('businessName','Planning merchant','shopName','Books','attemptId','planning-merchant-create-'||suffix));merchant_shop:=(r#>>'{shop,id}')::uuid;perform pg_temp.planning_assert(merchant_shop is not null,'refund fixture merchant created');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);
 r:=pg_temp.planning_call('payment.pay',jsonb_build_object('shopId',merchant_shop,'amount',300,'budgetCategoryId',food,'pin',pin,'attemptId','planning-merchant-pay-'||suffix));merchant_payment:=(r#>>'{receipt,id}')::uuid;perform pg_temp.planning_assert(r->>'ok'='true','merchant payment binds original budget source');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id',sb)::text,true);
 r:=pg_temp.planning_call('payment.refund',jsonb_build_object('paymentId',merchant_payment,'amount',150,'pin',pin,'attemptId','planning-merchant-partial-refund-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','partial merchant refund posted');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);
 r:=pg_temp.planning_call('plan.get');perform pg_temp.planning_assert((select(value->>'spent')::bigint from jsonb_array_elements(r#>'{plan,categories}')where value->>'id'=food::text)=550,'partial refund restores original category allocation');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id',sb)::text,true);
 r:=pg_temp.planning_call('payment.refund',jsonb_build_object('paymentId',merchant_payment,'amount',150,'pin',pin,'attemptId','planning-merchant-final-refund-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','final merchant refund posted');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);
 r:=pg_temp.planning_call('plan.get');perform pg_temp.planning_assert((select(value->>'spent')::bigint from jsonb_array_elements(r#>'{plan,categories}')where value->>'id'=food::text)=400,'full refund restores all original budget spending');
 r:=pg_temp.planning_call('insight.get');perform pg_temp.planning_assert((r#>>'{insights,periodSpent}')::bigint=500,'spending insight nets actual refunds against original spending');
 select balance into before_balance from lumo_private.accounts where owner_user_id=a and kind='consumer';
 r:=pg_temp.planning_call('money.record',jsonb_build_object('name','My MoMo','kind','momo','balance',50000,'note','Manual check','attemptId','planning-external-create-'||suffix));manual_record:=(r#>>'{record,id}')::uuid;perform pg_temp.planning_assert(manual_record is not null and(r#>>'{record,balance}')::bigint=50000,'manual external balance persisted');
 r:=pg_temp.planning_call('money.record',jsonb_build_object('recordId',manual_record,'name','My MoMo','kind','momo','balance',45000,'note','Updated manually','attemptId','planning-external-update-'||suffix));perform pg_temp.planning_assert(r->>'ok'='true','manual external balance update');
 r:=pg_temp.planning_call('money.history',jsonb_build_object('recordId',manual_record));perform pg_temp.planning_assert(jsonb_array_length(r->'history')=2,'external update history retained');
 r:=pg_temp.planning_call('money.overview');perform pg_temp.planning_assert((r#>>'{overview,everyday}')::bigint=before_balance and(r#>>'{overview,external}')::bigint=45000,'manual external money never becomes spendable');
 r:=pg_temp.planning_call('money.chat',jsonb_build_object('question','What do people owe me?'));perform pg_temp.planning_assert(r->>'ok'='true'and r->>'grounded'='true'and r->>'engine'='ledger-calculations'and(r->>'answer')like'%expected money%','Money Chat grounded in actual accepted IOUs');
 r:=pg_temp.planning_call('money.chat',jsonb_build_object('question','Will bitcoin double?'));perform pg_temp.planning_assert((r->>'answer')like'%cannot see%','unsupported chat does not pretend external financial knowledge');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',x,'role','authenticated','session_id',sx)::text,true);
 r:=pg_temp.planning_call('plan.get');perform pg_temp.planning_assert(jsonb_array_length(r->'boxes')=0 and jsonb_array_length(r->'ious')=0,'outsider cannot read others plan boxes or IOUs');
 r:=pg_temp.planning_call('box.withdraw',jsonb_build_object('boxId',plain_box,'amount',1,'pin',pin,'attemptId','planning-outsider-withdraw-'||suffix));perform pg_temp.planning_assert(r->>'code'='FORBIDDEN','outsider cannot withdraw box');
 r:=pg_temp.planning_call('money.history',jsonb_build_object('recordId',manual_record));perform pg_temp.planning_assert(r->>'code'='FORBIDDEN','outsider cannot read external money history');
 r:=pg_temp.planning_call('iou.pay',jsonb_build_object('iouId',iou_id,'amount',1,'pin',pin,'attemptId','planning-outsider-iou-'||suffix));perform pg_temp.planning_assert(r->>'code'='FORBIDDEN','outsider cannot pay or alter private IOU');
 r:=pg_temp.planning_call('box.list');perform pg_temp.planning_assert(r->'partnerInvitations'='[]'::jsonb and r->'releaseRequests'='[]'::jsonb,'outsider cannot read private partner inbox');
 delete from auth.sessions where id=sx;
 r:=pg_temp.planning_call('money.overview');perform pg_temp.planning_assert(r->>'code'='SESSION_REVOKED','revoked session cannot read planning');
 perform set_config('lumo.planning.report',jsonb_build_object('checks',current_setting('lumo.planning.checks')::integer,'testFixturesRolledBack',true)::text,true);
end $$;
set constraints all immediate;
select current_setting('lumo.planning.report')::jsonb as lumo_planning_test;
rollback;
